CREATE TABLE daily_operating_aggregates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregation_date date NOT NULL, scope_type text NOT NULL CHECK (scope_type IN ('store','district','company')), organization_id uuid REFERENCES organizations(id), district_id uuid REFERENCES districts(id), store_id uuid REFERENCES stores(id), gross_sales_minor bigint NOT NULL DEFAULT 0, discounts_minor bigint NOT NULL DEFAULT 0, refunds_minor bigint NOT NULL DEFAULT 0, net_sales_minor bigint NOT NULL DEFAULT 0, collected_revenue_minor bigint NOT NULL DEFAULT 0, outstanding_revenue_minor bigint NOT NULL DEFAULT 0, estimated_hourly_wages_minor bigint NOT NULL DEFAULT 0, estimated_commissions_minor bigint NOT NULL DEFAULT 0, finalized_payroll_minor bigint, source_status text NOT NULL CHECK (source_status IN ('estimated','finalized')), refreshed_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), CHECK ((scope_type='company' AND organization_id IS NOT NULL AND district_id IS NULL AND store_id IS NULL) OR (scope_type='district' AND district_id IS NOT NULL AND store_id IS NULL) OR (scope_type='store' AND store_id IS NOT NULL)), UNIQUE NULLS NOT DISTINCT(aggregation_date, scope_type, organization_id, district_id, store_id));
CREATE INDEX daily_operating_aggregates_scope_date_idx ON daily_operating_aggregates (scope_type, aggregation_date DESC);
